const positions={chain:[[100,173],[300,173],[500,173]],loop:[[100,160],[300,160],[500,160]],parallel:[[155,122],[155,254],[462,186]],tree:[[105,186],[425,116],[425,252]],stack:[[112,121],[300,183],[488,245]]};
const arrow=(x1,y1,x2,y2)=>{const a=Math.atan2(y2-y1,x2-x1),dx=Math.cos(a),dy=Math.sin(a),sx=x1+dx*55,sy=y1+dy*55,ex=x2-dx*59,ey=y2-dy*59;return path(`M${sx.toFixed(2)} ${sy.toFixed(2)}L${ex.toFixed(2)} ${ey.toFixed(2)}`,'none',C.line,2.5)+path(`M${(ex-dx*10-dy*5).toFixed(2)} ${(ey-dy*10+dx*5).toFixed(2)}L${ex.toFixed(2)} ${ey.toFixed(2)}L${(ex-dx*10+dy*5).toFixed(2)} ${(ey-dy*10-dx*5).toFixed(2)}`,'none',C.teal,2.5)};
function shortLines(value,limit){const words=String(value).split(' ');if(words.length===1){const chars=Array.from(value);return chars.length>limit?[chars.slice(0,limit).join(''),chars.slice(limit).join('')]:[value]}const lines=[''];for(const word of words){if((lines.at(-1)+' '+word).trim().length>limit&&lines.at(-1)&&lines.length<2)lines.push(word);else lines[lines.length-1]+=(lines.at(-1)?' ':'')+word}return lines}
export function electronicsGeometry(courseId,{zh=true,labels=true,focus=-1}={}){
 const subject=ELECTRONICS_SUBJECTS[courseId];if(!subject)return '';const p=positions[subject.layout]||positions.chain;
 const pairs=subject.layout==='parallel'?[[0,2],[1,2]]:subject.layout==='tree'?[[0,1],[0,2]]:[[0,1],[1,2]];
 let out=pairs.map(([a,b])=>arrow(...p[a],...p[b])).join('');
 if(subject.layout==='loop'){const targetX=p[subject.feedbackTarget||0][0];out+=path(`M555 160H573V91H${targetX}V105`,'none',C.line,2)+path(`M${targetX-5} 96L${targetX} 105 ${targetX+5} 96`,'none',C.teal,2)}
 subject.nodes.forEach((node,index)=>{const [x,y]=p[index];out+=`<g transform="translate(${x} ${y})">${focus===index?circle(0,0,52,'#e8d8b755'):''}${electronicsGlyph(node.kind)}</g>`;if(labels)out+=shortLines(node[zh?'zh':'en'],zh?14:26).map((line,i)=>text(x,y+62+i*14,line,zh?13:10.5)).join('')});return out;
}
export function electronicsVisualFamily(courseId){return ELECTRONICS_SUBJECTS[courseId]?.family||null}
export function renderElectronicsVisual(courseId,{zh=true,mode='full',focus=-1}={}){
 const s=ELECTRONICS_SUBJECTS[courseId];if(!s)return '';const title=zh?s.title:s.titleEn,desc=zh?'原創功能關聯示意；不是實際接線圖、比例圖或帶電操作程序。':'Original functional relationships; not actual wiring, a scaled drawing or an energized-work procedure.';
 return `<svg xmlns="http://www.w3.org/2000/svg" class="electronics-subject-visual" viewBox="0 0 600 370" role="img" aria-label="${esc(title+' — '+desc)}" data-course="${courseId}" data-family="${esc(s.family)}" data-original="true"><title>${esc(title)}</title><desc>${esc(desc)}</desc>${box(0,0,600,370,C.pale,14)}${text(60,24,courseId.toUpperCase(),11,C.teal)}${text(454,24,zh?'原創功能圖 · 非接線指南':'ORIGINAL FUNCTIONAL MODEL',10,C.teal)}${shortLines(title,zh?30:72).map((line,i)=>text(300,52+i*17,line,zh?17:12)).join('')}<g data-geometry="${courseId}">${electronicsGeometry(courseId,{zh,labels:mode!=='icon',focus})}</g>${mode==='icon'?'':text(300,350,zh?'圖示與箭頭表示功能關聯；實際設計需逐一驗證。':'Symbols and arrows show functional relationships, requiring validation.',zh?12:10,C.teal)}</svg>`;
}
export function renderElectronicsIcon(courseId,{en=false}={}){
 const s=ELECTRONICS_SUBJECTS[courseId];if(!s)return '';return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 88 104" class="project-icon" role="img" aria-label="${esc(en?s.titleEn:s.title)}" data-project-icon="${courseId}" data-subject-art="${courseId}" data-original="true">${box(1,1,86,86,C.pale,14)}${s.nodes.map((node,i)=>`<g transform="translate(${[24,64,44][i]} ${[28,28,64][i]}) scale(.32)">${electronicsGlyph(node.kind)}</g>`).join('')}${path('M33 31H53M58 38L47 51M28 38L40 51','none',C.line,1.5)}${text(44,100,courseId.toUpperCase(),9,C.teal)}</svg>`;
}
